# Hindi / Gujarati text for Economics Ch 2 lesson, sections 4-6.
TEXT_B = {
 "s4.thm.title": ("ज़्यादा रोज़गार और काम की परिस्थितियाँ", "વધુ રોજગાર અને કામની પરિસ્થિતિઓ"),
 "s4.thm.body": (
  "**ज़्यादा रोज़गार कैसे पैदा करें:**\n"
  "- **सिंचाई:** अगर सरकार लक्ष्मी जैसे कई खेतों की सिंचाई के लिए बाँध और नहरें बनाए, तो कृषि क्षेत्रक में ही बहुत रोज़गार पैदा हो सकता है।\n"
  "- **परिवहन और भंडारण:** गाँवों से बाज़ारों तक बेहतर सड़कें और परिवहन, और भंडारण की सुविधाएँ किसानों को फ़सल बेचने में मदद करती हैं और परिवहन तथा व्यापार में रोज़गार पैदा करती हैं।\n"
  "- **सस्ता क़र्ज़:** अगर किसानों को बैंकों से उचित ब्याज दर पर क़र्ज़ मिले, तो वे बीज, खाद और उपकरण ख़रीदकर ज़्यादा उगा सकते हैं।\n"
  "- **अर्ध-ग्रामीण इलाक़ों में उद्योग और सेवाएँ:** **दाल मिल**, शीत भंडार, शहद इकट्ठा करना और सब्ज़ियों तथा फलों का प्रसंस्करण जैसे उद्योग गाँवों के पास रोज़गार पैदा कर सकते हैं।\n"
  "- **शिक्षा, स्वास्थ्य और पर्यटन:** पूर्व **योजना आयोग** (अब **नीति आयोग**) के एक अध्ययन के अनुसार अकेले **शिक्षा क्षेत्रक** में लगभग **20 लाख नौकरियाँ** पैदा हो सकती हैं। स्वास्थ्य सेवाएँ सुधारने पर ज़्यादा डॉक्टर, नर्स और स्वास्थ्यकर्मी चाहिए; पर्यटन से भी रोज़गार बढ़ सकता है।\n\n"
  "**मनरेगा 2005:** केंद्र सरकार ने भारत के 625 ज़िलों में **काम का अधिकार** लागू करने वाला क़ानून बनाया, जिसे **महात्मा गांधी राष्ट्रीय ग्रामीण रोज़गार गारंटी अधिनियम 2005 (मनरेगा 2005)** कहते हैं।\n"
  "- ग्रामीण क्षेत्रों में काम करने में सक्षम और ज़रूरतमंद सभी लोगों को सरकार द्वारा **साल में 100 दिन के रोज़गार की गारंटी** दी गई है।\n"
  "- अगर सरकार रोज़गार देने में विफल रहे, तो वह लोगों को **बेरोज़गारी भत्ता** देगी।\n"
  "- प्रस्तावित नौकरियों में से **एक-तिहाई महिलाओं के लिए आरक्षित** हैं।\n"
  "- उन कामों को प्राथमिकता दी जाती है जो भविष्य में **भूमि से उत्पादन बढ़ाने** में मदद करें।\n\n"
  "**संगठित और असंगठित क्षेत्रक** (**रोज़गार की परिस्थितियों** के आधार पर वर्गीकरण):\n"
  "- **संगठित क्षेत्रक** में वे उद्यम या कार्य-स्थान आते हैं जहाँ रोज़गार की अवधि **नियमित** होती है, इसलिए लोगों के पास **सुनिश्चित काम** होता है। वे **सरकार द्वारा पंजीकृत** होते हैं और उन्हें सरकारी नियमों का पालन करना होता है, जो **कारख़ाना अधिनियम, न्यूनतम मज़दूरी अधिनियम, उपदान भुगतान अधिनियम और दुकान एवं प्रतिष्ठान अधिनियम** जैसे क़ानूनों में दिए हैं। कामगारों को **रोज़गार की सुरक्षा**, निश्चित काम के घंटे, **अतिरिक्त समय (ओवरटाइम)** का भुगतान, सवेतन छुट्टी, अवकाश के दिनों का भुगतान, **भविष्य निधि, उपदान (ग्रेच्युटी)**, चिकित्सा लाभ और सेवानिवृत्ति पर **पेंशन** मिलती है।\n"
  "- **असंगठित क्षेत्रक** में **छोटी और बिखरी हुई इकाइयाँ** होती हैं जो अधिकतर **सरकारी नियंत्रण से बाहर** होती हैं। नियम-क़ानून हैं, पर उनका पालन नहीं होता। नौकरियाँ **कम वेतन वाली और अक्सर अनियमित** होती हैं। ओवरटाइम, सवेतन छुट्टी, अवकाश या बीमारी की छुट्टी का कोई प्रावधान नहीं होता। रोज़गार **सुरक्षित नहीं**: लोगों को बिना कारण काम छोड़ने को कहा जा सकता है, और कुछ मौसमों में काम घट जाता है।\n"
  "- 1990 के दशक से बहुत से कामगारों ने **संगठित क्षेत्रक में नौकरियाँ खोई** हैं और उन्हें कम आय वाले असंगठित क्षेत्रक में काम करना पड़ा है।\n\n"
  "**असंगठित क्षेत्रक के कामगारों की सुरक्षा:** **ग्रामीण क्षेत्रों** में असंगठित क्षेत्रक में मुख्यतः **भूमिहीन खेतिहर मज़दूर, छोटे और सीमांत किसान, बटाईदार और कारीगर** (बुनकर, लोहार, बढ़ई और सुनार) आते हैं। **शहरी क्षेत्रों** में इसमें लघु उद्योग, निर्माण, व्यापार और परिवहन के **अनियत कामगार**, **फेरीवाले, बोझा ढोने वाले, कपड़े सिलने वाले और कबाड़ बीनने वाले** आते हैं। अनुसूचित जाति, जनजाति और पिछड़े समुदायों के कामगार अक्सर इसी में होते हैं। उन्हें **मज़दूरी, सुरक्षा और स्वास्थ्य** के मामले में संरक्षण चाहिए, और छोटे उत्पादकों को कच्चा माल ख़रीदने और उत्पाद बेचने में सहारा चाहिए।",
  "**વધુ રોજગાર કેવી રીતે ઊભો કરવો:**\n"
  "- **સિંચાઈ:** જો સરકાર લક્ષ્મી જેવાં ઘણાં ખેતરોની સિંચાઈ માટે બંધ અને નહેરો બાંધે, તો ખેતી ક્ષેત્રમાં જ ઘણો રોજગાર ઊભો થઈ શકે.\n"
  "- **પરિવહન અને સંગ્રહ:** ગામડાંથી બજારો સુધી વધુ સારા રસ્તા અને પરિવહન, અને સંગ્રહની સુવિધાઓ ખેડૂતોને પાક વેચવામાં મદદ કરે છે અને પરિવહન તથા વેપારમાં રોજગાર ઊભો કરે છે.\n"
  "- **સસ્તું ધિરાણ:** જો ખેડૂતોને બૅન્કોમાંથી વાજબી વ્યાજ દરે લોન મળે, તો તેઓ બિયારણ, ખાતર અને સાધનો ખરીદી વધુ ઉગાડી શકે.\n"
  "- **અર્ધ-ગ્રામીણ વિસ્તારોમાં ઉદ્યોગો અને સેવાઓ:** **દાળ મિલ**, શીતગૃહ, મધ એકઠું કરવું અને શાકભાજી તથા ફળોનું પ્રોસેસિંગ જેવા ઉદ્યોગો ગામડાં પાસે રોજગાર ઊભો કરી શકે.\n"
  "- **શિક્ષણ, આરોગ્ય અને પ્રવાસન:** અગાઉના **આયોજન પંચ** (હવે **નીતિ આયોગ**)ના એક અભ્યાસ મુજબ ફક્ત **શિક્ષણ ક્ષેત્ર**માં જ આશરે **20 લાખ નોકરીઓ** ઊભી થઈ શકે. આરોગ્ય સેવાઓ સુધારીએ તો વધુ ડૉક્ટરો, નર્સો અને આરોગ્ય કર્મચારીઓ જોઈએ; પ્રવાસનથી પણ રોજગાર વધી શકે.\n\n"
  "**મનરેગા 2005:** કેન્દ્ર સરકારે ભારતના 625 જિલ્લાઓમાં **કામના અધિકાર**ને અમલમાં મૂકતો કાયદો ઘડ્યો, જેને **મહાત્મા ગાંધી રાષ્ટ્રીય ગ્રામીણ રોજગાર ગૅરંટી અધિનિયમ 2005 (મનરેગા 2005)** કહે છે.\n"
  "- ગ્રામીણ વિસ્તારોમાં કામ કરવા સક્ષમ અને જરૂરિયાતમંદ બધા લોકોને સરકાર દ્વારા **વર્ષમાં 100 દિવસના રોજગારની ગૅરંટી** અપાઈ છે.\n"
  "- જો સરકાર રોજગાર આપવામાં નિષ્ફળ જાય, તો તે લોકોને **બેરોજગારી ભથ્થું** આપશે.\n"
  "- સૂચિત નોકરીઓમાંથી **એક-તૃતીયાંશ સ્ત્રીઓ માટે અનામત** છે.\n"
  "- એવાં કામોને પ્રાધાન્ય અપાય છે જે ભવિષ્યમાં **જમીનમાંથી ઉત્પાદન વધારવા**માં મદદ કરે.\n\n"
  "**સંગઠિત અને અસંગઠિત ક્ષેત્ર** (**રોજગારની પરિસ્થિતિ**ના આધારે વર્ગીકરણ):\n"
  "- **સંગઠિત ક્ષેત્ર**માં એવાં સાહસો કે કાર્યસ્થળો આવે છે જ્યાં રોજગારની શરતો **નિયમિત** હોય છે, તેથી લોકો પાસે **ખાતરીપૂર્વકનું કામ** હોય છે. તે **સરકાર દ્વારા નોંધાયેલાં** હોય છે અને તેમણે સરકારના નિયમોનું પાલન કરવું પડે છે, જે **કારખાના ધારો, લઘુતમ વેતન ધારો, ગ્રેચ્યુઇટી ચુકવણી ધારો અને દુકાન અને સંસ્થા ધારો** જેવા કાયદાઓમાં આપેલા છે. કામદારોને **રોજગારની સલામતી**, નક્કી કામના કલાકો, **ઓવરટાઇમ**નું વેતન, પગાર સાથેની રજા, રજાના દિવસોનું વેતન, **પ્રૉવિડન્ટ ફંડ, ગ્રેચ્યુઇટી**, તબીબી લાભો અને નિવૃત્તિ પછી **પેન્શન** મળે છે.\n"
  "- **અસંગઠિત ક્ષેત્ર**માં **નાનાં અને છૂટાંછવાયાં એકમો** હોય છે જે મોટે ભાગે **સરકારી નિયંત્રણ બહાર** હોય છે. નિયમો છે, પણ તેનું પાલન થતું નથી. નોકરીઓ **ઓછા વેતનવાળી અને ઘણી વાર અનિયમિત** હોય છે. ઓવરટાઇમ, પગાર સાથેની રજા, તહેવારની રજા કે માંદગીની રજાની કોઈ જોગવાઈ નથી. રોજગાર **સલામત નથી**: લોકોને કારણ વિના છૂટા કરી શકાય, અને કેટલીક ઋતુઓમાં કામ ઘટી જાય છે.\n"
  "- 1990ના દાયકાથી ઘણા કામદારોએ **સંગઠિત ક્ષેત્રમાં નોકરીઓ ગુમાવી** છે અને તેમને ઓછી આવકવાળા અસંગઠિત ક્ષેત્રમાં કામ કરવું પડ્યું છે.\n\n"
  "**અસંગઠિત ક્ષેત્રના કામદારોનું રક્ષણ:** **ગ્રામીણ વિસ્તારોમાં** અસંગઠિત ક્ષેત્રમાં મુખ્યત્વે **જમીનવિહોણા ખેતમજૂરો, નાના અને સીમાંત ખેડૂતો, ભાગિયા ખેડૂતો અને કારીગરો** (વણકરો, લુહાર, સુથાર અને સોની) આવે છે. **શહેરી વિસ્તારોમાં** તેમાં નાના ઉદ્યોગો, બાંધકામ, વેપાર અને પરિવહનના **છૂટક કામદારો**, **ફેરિયા, માથે બોજ ઊંચકનારા, કપડાં સીવનારા અને કચરો વીણનારા** આવે છે. અનુસૂચિત જાતિ, જનજાતિ અને પછાત સમુદાયોના કામદારો ઘણી વાર તેમાં હોય છે. તેમને **વેતન, સલામતી અને આરોગ્ય**ની બાબતમાં રક્ષણ જોઈએ, અને નાના ઉત્પાદકોને કાચો માલ ખરીદવામાં અને માલ વેચવામાં ટેકો જોઈએ."),
 "s4.table.title": ("संगठित और असंगठित क्षेत्रक", "સંગઠિત અને અસંગઠિત ક્ષેત્ર"),
 "s4.table.body": (
  "| संगठित क्षेत्रक | असंगठित क्षेत्रक |\n|---|---|\n| सरकार द्वारा **पंजीकृत** उद्यम; कारख़ाना अधिनियम, न्यूनतम मज़दूरी अधिनियम, उपदान भुगतान अधिनियम और दुकान एवं प्रतिष्ठान अधिनियम जैसे नियमों का पालन | छोटी और बिखरी इकाइयाँ, अधिकतर **सरकारी नियंत्रण से बाहर**; नियम हैं पर पालन नहीं |\n"
  "| **नियमित** काम और **रोज़गार की सुरक्षा** | नौकरियाँ **कम वेतन वाली, अनियमित** और असुरक्षित; बिना कारण निकाला जा सकता है |\n"
  "| काम के निश्चित घंटे; **ओवरटाइम** का भुगतान | लंबे घंटे; ओवरटाइम नहीं |\n| **सवेतन छुट्टी**, अवकाश, भविष्य निधि, उपदान, चिकित्सा लाभ, पेंशन | सवेतन छुट्टी, अवकाश या बीमारी की छुट्टी नहीं |\n"
  "| सुरक्षित कार्य-वातावरण, पीने का पानी | अक्सर असुरक्षित परिस्थितियाँ |",
  "| સંગઠિત ક્ષેત્ર | અસંગઠિત ક્ષેત્ર |\n|---|---|\n| સરકાર દ્વારા **નોંધાયેલાં** સાહસો; કારખાના ધારો, લઘુતમ વેતન ધારો, ગ્રેચ્યુઇટી ચુકવણી ધારો અને દુકાન અને સંસ્થા ધારા જેવા નિયમોનું પાલન | નાનાં અને છૂટાંછવાયાં એકમો, મોટે ભાગે **સરકારી નિયંત્રણ બહાર**; નિયમો છે પણ પાલન નહિ |\n"
  "| **નિયમિત** કામ અને **રોજગારની સલામતી** | નોકરીઓ **ઓછા વેતનવાળી, અનિયમિત** અને અસલામત; કારણ વિના છૂટા કરી શકાય |\n"
  "| કામના નક્કી કલાકો; **ઓવરટાઇમ**નું વેતન | લાંબા કલાકો; ઓવરટાઇમ નહિ |\n| **પગાર સાથેની રજા**, તહેવારની રજા, પ્રૉવિડન્ટ ફંડ, ગ્રેચ્યુઇટી, તબીબી લાભ, પેન્શન | પગાર સાથેની રજા, તહેવારની રજા કે માંદગીની રજા નહિ |\n"
  "| સલામત કાર્ય-વાતાવરણ, પીવાનું પાણી | ઘણી વાર અસલામત પરિસ્થિતિ |"),
 "s5.thm.title": ("उद्यमों का स्वामित्व", "સાહસોની માલિકી"),
 "s5.thm.body": (
  "आर्थिक गतिविधियों को बाँटने का एक और तरीक़ा यह है कि **परिसंपत्तियों का मालिक कौन है और सेवाएँ देने की ज़िम्मेदारी किसकी है**।\n"
  "- **सार्वजनिक क्षेत्रक** में **अधिकतर परिसंपत्तियों पर सरकार का स्वामित्व** होता है और सरकार ही सभी सेवाएँ देती है। **भारतीय रेलवे** और **डाकघर** इसके उदाहरण हैं।\n"
  "- **निजी क्षेत्रक** में परिसंपत्तियों का स्वामित्व और सेवाएँ देने की ज़िम्मेदारी **निजी व्यक्तियों या कंपनियों** के हाथ में होती है। **टाटा आयरन एंड स्टील कंपनी लिमिटेड (TISCO)** और **रिलायंस इंडस्ट्रीज़ लिमिटेड (RIL)** जैसी कंपनियाँ निजी स्वामित्व में हैं।\n"
  "- निजी क्षेत्रक की गतिविधियाँ **लाभ कमाने** के उद्देश्य से चलती हैं। उनकी सेवाओं के लिए हमें इन व्यक्तियों और कंपनियों को पैसा देना पड़ता है। सार्वजनिक क्षेत्रक का उद्देश्य **केवल लाभ कमाना नहीं** है; सरकार अपनी सेवाओं के ख़र्च के लिए **करों** और दूसरे तरीक़ों से पैसा जुटाती है।\n\n"
  "**सरकार कुछ गतिविधियाँ ख़ुद क्यों करती है:**\n"
  "- समाज के लिए कई ज़रूरी चीज़ें ऐसी हैं जिन्हें निजी क्षेत्रक उचित क़ीमत पर नहीं देगा। इनमें से कुछ के लिए **बहुत बड़ी राशि ख़र्च** करनी पड़ती है जो निजी क्षेत्रक की क्षमता से बाहर है, और इन सुविधाओं का इस्तेमाल करने वाले हज़ारों लोगों से पैसा वसूलना संभव नहीं, जैसे **सड़कें, पुल, रेलवे, बंदरगाह, बिजली बनाना और बाँधों से सिंचाई**। इसलिए सरकार यह भारी ख़र्च उठाती है और सुनिश्चित करती है कि ये सुविधाएँ सबको मिलें।\n"
  "- कुछ गतिविधियों को सरकार का सहारा चाहिए। जैसे, **उत्पादन लागत पर बिजली** बेचने से कई लघु उद्योगों की उत्पादन लागत बढ़ सकती है, इसलिए सरकार बिजली ऐसी दरों पर बनाती और देती है जो ये उद्योग चुका सकें।\n"
  "- भारत सरकार किसानों से **गेहूँ और चावल** **उचित मूल्य** पर ख़रीदती है, अपने गोदामों में रखती है, और **राशन दुकानों के ज़रिए उपभोक्ताओं को कम दाम पर** बेचती है। लागत का कुछ हिस्सा सरकार उठाती है। इस तरह वह किसानों और उपभोक्ताओं दोनों की मदद करती है।\n"
  "- कई गतिविधियाँ **सरकार की प्राथमिक ज़िम्मेदारी** हैं: सबके लिए **स्वास्थ्य और शिक्षा** की सुविधाएँ देना, ठीक से स्कूल चलाना और अच्छी शिक्षा देना, और ख़ासकर बच्चों और ग़रीबों के पोषण का ध्यान रखना।",
  "આર્થિક પ્રવૃત્તિઓનું વર્ગીકરણ કરવાની બીજી રીત એ છે કે **અસ્કયામતોનો માલિક કોણ છે અને સેવાઓ પૂરી પાડવાની જવાબદારી કોની છે**.\n"
  "- **જાહેર ક્ષેત્ર**માં **મોટા ભાગની અસ્કયામતોની માલિકી સરકારની** હોય છે અને સરકાર જ બધી સેવાઓ પૂરી પાડે છે. **ભારતીય રેલવે** અને **ટપાલ કચેરી** તેનાં ઉદાહરણ છે.\n"
  "- **ખાનગી ક્ષેત્ર**માં અસ્કયામતોની માલિકી અને સેવાઓ પૂરી પાડવાની જવાબદારી **ખાનગી વ્યક્તિઓ કે કંપનીઓ**ના હાથમાં હોય છે. **ટાટા આયર્ન ઍન્ડ સ્ટીલ કંપની લિમિટેડ (TISCO)** અને **રિલાયન્સ ઇન્ડસ્ટ્રીઝ લિમિટેડ (RIL)** જેવી કંપનીઓ ખાનગી માલિકીની છે.\n"
  "- ખાનગી ક્ષેત્રની પ્રવૃત્તિઓ **નફો કમાવાના** હેતુથી ચાલે છે. તેમની સેવાઓ માટે આપણે આ વ્યક્તિઓ અને કંપનીઓને પૈસા ચૂકવવા પડે છે. જાહેર ક્ષેત્રનો હેતુ **ફક્ત નફો કમાવો નથી**; સરકાર પોતાની સેવાઓના ખર્ચ માટે **કરવેરા** અને બીજી રીતે પૈસા ઊભા કરે છે.\n\n"
  "**સરકાર કેટલીક પ્રવૃત્તિઓ પોતે કેમ કરે છે:**\n"
  "- સમાજ માટે ઘણી જરૂરી વસ્તુઓ એવી છે જે ખાનગી ક્ષેત્ર વાજબી કિંમતે નહિ આપે. તેમાંથી કેટલીક માટે **ખૂબ મોટી રકમનો ખર્ચ** કરવો પડે છે જે ખાનગી ક્ષેત્રની ક્ષમતા બહાર છે, અને આ સુવિધાઓ વાપરતા હજારો લોકો પાસેથી પૈસા ઉઘરાવવા શક્ય નથી, જેમ કે **રસ્તા, પુલ, રેલવે, બંદરો, વીજળી ઉત્પાદન અને બંધ દ્વારા સિંચાઈ**. તેથી સરકાર આ ભારે ખર્ચ ઉપાડે છે અને ખાતરી કરે છે કે આ સુવિધાઓ બધાને મળે.\n"
  "- કેટલીક પ્રવૃત્તિઓને સરકારના ટેકાની જરૂર છે. જેમ કે, **ઉત્પાદન ખર્ચે વીજળી** વેચવાથી ઘણા નાના ઉદ્યોગોનો ઉત્પાદન ખર્ચ વધી શકે, તેથી સરકાર વીજળી એવા દરે ઉત્પન્ન કરે છે અને પૂરી પાડે છે જે આ ઉદ્યોગો પરવડી શકે.\n"
  "- ભારત સરકાર ખેડૂતો પાસેથી **ઘઉં અને ચોખા** **વાજબી ભાવે** ખરીદે છે, પોતાનાં ગોદામોમાં રાખે છે, અને **રૅશનની દુકાનો દ્વારા ગ્રાહકોને ઓછા ભાવે** વેચે છે. ખર્ચનો કેટલોક ભાગ સરકાર ઉપાડે છે. આ રીતે તે ખેડૂતો અને ગ્રાહકો બંનેને મદદ કરે છે.\n"
  "- ઘણી પ્રવૃત્તિઓ **સરકારની પ્રાથમિક જવાબદારી** છે: બધા માટે **આરોગ્ય અને શિક્ષણ**ની સુવિધાઓ, યોગ્ય રીતે શાળાઓ ચલાવવી અને ગુણવત્તાવાળું શિક્ષણ આપવું, અને ખાસ કરીને બાળકો અને ગરીબોના પોષણની કાળજી લેવી."),
 "s6.memory.title": ("याद रखने की तरकीबें", "યાદ રાખવાની યુક્તિઓ"),
 "s6.memory.body": (
  "- **वर्गीकरण के तीन तरीक़े: \"प्रकृति–परिस्थिति–मालिक\"**: गतिविधि की प्रकृति (प्राथमिक, द्वितीयक, तृतीयक); रोज़गार की परिस्थितियाँ (संगठित, असंगठित); स्वामित्व (सार्वजनिक, निजी)।\n"
  "- **प्रा-द्वि-तृ = उगाओ, बनाओ, पहुँचाओ**: प्राथमिक उगाता/निकालता है, द्वितीयक बनाता है, तृतीयक पहुँचाता और सेवा देता है।\n"
  "- **GDP = केवल अंतिम वस्तुएँ** (बिस्कुट, आटा और गेहूँ नहीं)।\n- **तृतीयक क्यों बढ़ा: \"बु-वि-आ-न\"**: बुनियादी सेवाएँ, कृषि-उद्योग का विकास, आय में वृद्धि, नई IT सेवाएँ।\n"
  "- **मनरेगा: \"2005, 100 दिन, 1/3 महिलाएँ, भत्ता\"।**\n- **संगठित क्षेत्रक के क़ानून: \"का-न्यू-उ-दु\"**: कारख़ाना, न्यूनतम मज़दूरी, उपदान, दुकान एवं प्रतिष्ठान।",
  "- **વર્ગીકરણની ત્રણ રીતો: \"સ્વરૂપ–પરિસ્થિતિ–માલિક\"**: પ્રવૃત્તિનું સ્વરૂપ (પ્રાથમિક, દ્વિતીય, તૃતીય); રોજગારની પરિસ્થિતિ (સંગઠિત, અસંગઠિત); માલિકી (જાહેર, ખાનગી).\n"
  "- **પ્રા-દ્વિ-તૃ = ઉગાડો, બનાવો, પહોંચાડો**: પ્રાથમિક ઉગાડે/કાઢે, દ્વિતીય બનાવે, તૃતીય પહોંચાડે અને સેવા આપે.\n"
  "- **GDP = ફક્ત અંતિમ વસ્તુઓ** (બિસ્કિટ, લોટ અને ઘઉં નહિ).\n- **તૃતીય કેમ વધ્યું: \"પા-વિ-આ-ન\"**: પાયાની સેવાઓ, ખેતી-ઉદ્યોગનો વિકાસ, આવકમાં વધારો, નવી IT સેવાઓ.\n"
  "- **મનરેગા: \"2005, 100 દિવસ, 1/3 સ્ત્રીઓ, ભથ્થું\".**\n- **સંગઠિત ક્ષેત્રના કાયદા: \"કા-લ-ગ્રે-દુ\"**: કારખાના, લઘુતમ વેતન, ગ્રેચ્યુઇટી, દુકાન અને સંસ્થા."),
 "s6.mistakes.title": ("आम ग़लतियाँ", "સામાન્ય ભૂલો"),
 "s6.mistakes.body": (
  "1. खनन को द्वितीयक गतिविधि कहना: खनन **प्राथमिक** है।\n2. GDP में मध्यवर्ती वस्तुएँ जोड़ना: केवल **अंतिम वस्तुएँ और सेवाएँ** गिनी जाती हैं।\n"
  "3. यह कहना कि तृतीयक क्षेत्रक सबसे बड़ा रोज़गार देने वाला है: यह सबसे बड़ा **उत्पादक** है; सबसे बड़ा रोज़गार देने वाला **प्राथमिक** क्षेत्रक है।\n"
  "4. संगठित/असंगठित को सार्वजनिक/निजी से मिलाना: पहला **रोज़गार की परिस्थितियों** पर है, दूसरा **स्वामित्व** पर।\n"
  "5. यह कहना कि प्रच्छन्न बेरोज़गारी दिखाई देती है: यह **छिपी** होती है; खुली बेरोज़गारी दिखाई देती है।\n6. लिखना कि मनरेगा सालभर नौकरी की गारंटी देता है: यह **100 दिन** की गारंटी देता है।",
  "1. ખાણકામને દ્વિતીય પ્રવૃત્તિ કહેવી: ખાણકામ **પ્રાથમિક** છે.\n2. GDPમાં મધ્યવર્તી વસ્તુઓ ઉમેરવી: ફક્ત **અંતિમ વસ્તુઓ અને સેવાઓ** ગણાય છે.\n"
  "3. કહેવું કે તૃતીય ક્ષેત્ર સૌથી મોટું રોજગારદાતા છે: તે સૌથી મોટું **ઉત્પાદક** છે; સૌથી મોટું રોજગારદાતા **પ્રાથમિક** ક્ષેત્ર છે.\n"
  "4. સંગઠિત/અસંગઠિતને જાહેર/ખાનગી સાથે ભેળવવું: પહેલું **રોજગારની પરિસ્થિતિ** પર છે, બીજું **માલિકી** પર.\n"
  "5. કહેવું કે છૂપી બેરોજગારી દેખાય છે: તે **છૂપી** હોય છે; ખુલ્લી બેરોજગારી દેખાય છે.\n6. લખવું કે મનરેગા આખું વર્ષ નોકરીની ગૅરંટી આપે છે: તે **100 દિવસ**ની ગૅરંટી આપે છે."),
 "s6.tip.title": ("कक्षा में करके देखें", "વર્ગમાં કરી જુઓ"),
 "s6.tip.body": (
  "हर छात्र से उन पाँच वयस्कों के काम की सूची बनवाइए जिन्हें वह जानता है। बोर्ड पर सूची को तीन बार बाँटिए: क्षेत्रक के अनुसार (प्राथमिक, द्वितीयक, तृतीयक), रोज़गार की परिस्थितियों के अनुसार (संगठित, असंगठित) और स्वामित्व के अनुसार (सार्वजनिक, निजी)। चर्चा कीजिए कि हर बार कौन-सा समूह सबसे बड़ा है।",
  "દરેક વિદ્યાર્થી પાસે તે ઓળખતો હોય તેવા પાંચ પુખ્તોના કામની યાદી બનાવડાવો. બોર્ડ પર યાદીને ત્રણ વાર વહેંચો: ક્ષેત્ર મુજબ (પ્રાથમિક, દ્વિતીય, તૃતીય), રોજગારની પરિસ્થિતિ મુજબ (સંગઠિત, અસંગઠિત) અને માલિકી મુજબ (જાહેર, ખાનગી). ચર્ચા કરો કે દરેક વખતે કયું જૂથ સૌથી મોટું છે."),
 "s6.reflection.title": ("सोचिए और समझाइए", "વિચારો અને સમજાવો"),
 "s6.reflection.body": (
  "किसी ऐसे कामगार के बारे में सोचिए जिसे आप रोज़ देखते हैं, जैसे सब्ज़ीवाला, सुरक्षा गार्ड या डिलीवरी करने वाला। वह किस क्षेत्रक में है? क्या उसके पास रोज़गार की सुरक्षा, सवेतन छुट्टी और पेंशन है?",
  "રોજ જોતા હો તેવા કોઈ કામદાર વિશે વિચારો, જેમ કે શાકભાજીવાળા, સિક્યૉરિટી ગાર્ડ કે ડિલિવરી કરનાર. તે કયા ક્ષેત્રમાં છે? શું તેમની પાસે રોજગારની સલામતી, પગાર સાથેની રજા અને પેન્શન છે?"),
 "s6.connection.title": ("आगे कहाँ", "આગળ ક્યાં"),
 "s6.connection.body": (
  "- **अध्याय 1 (विकास):** आय, नौकरियाँ और कल्याण।\n- **अध्याय 3 (मुद्रा और साख):** किसानों और छोटे उत्पादकों के लिए क़र्ज़।\n- **भूगोल अध्याय 6 (विनिर्माण उद्योग):** द्वितीयक क्षेत्रक विस्तार से।",
  "- **પ્રકરણ 1 (વિકાસ):** આવક, નોકરીઓ અને કલ્યાણ.\n- **પ્રકરણ 3 (નાણું અને શાખ):** ખેડૂતો અને નાના ઉત્પાદકો માટે ધિરાણ.\n- **ભૂગોળ પ્રકરણ 6 (ઉત્પાદન ઉદ્યોગો):** દ્વિતીય ક્ષેત્ર વિગતે."),
 "s6.mastery.title": ("महारत चुनौती", "નિપુણતા પડકાર"),
 "s6.mastery.body": (
  "'प्राथमिक क्षेत्रक सबसे बड़ा रोज़गार देने वाला है, पर तृतीयक क्षेत्रक सबसे बड़ा उत्पादक।' इस स्थिति को समझाइए और ज़्यादा रोज़गार पैदा करने के दो तरीक़े सुझाइए, लगभग 120 शब्दों में।\n\n"
  "**आदर्श उत्तर:** 1973–74 से 2013–14 तक उत्पादन सबसे ज़्यादा तृतीयक क्षेत्रक में बढ़ा, जो 2013–14 में सबसे बड़ा उत्पादक क्षेत्रक बन गया। पर भारत के लगभग आधे कामगार अब भी प्राथमिक क्षेत्रक में हैं, क्योंकि द्वितीयक और तृतीयक क्षेत्रकों ने उत्पादन के अनुपात में रोज़गार नहीं बढ़ाया। "
  "इसलिए कृषि में प्रच्छन्न बेरोज़गारी है: खेतों पर ज़रूरत से ज़्यादा लोग काम करते हैं, इसलिए कुछ को हटाने से उत्पादन नहीं घटेगा। "
  "ग्रामीण क्षेत्रों में सिंचाई, सड़कें और भंडारण बनाकर, किसानों को सस्ता क़र्ज़ देकर, और अर्ध-ग्रामीण इलाक़ों में दाल मिल जैसे कृषि-प्रसंस्करण उद्योग लगाकर ज़्यादा रोज़गार पैदा हो सकता है। शिक्षा, स्वास्थ्य और पर्यटन का विस्तार, और मनरेगा जैसी योजनाएँ भी रोज़गार पैदा कर सकती हैं।",
  "'પ્રાથમિક ક્ષેત્ર સૌથી મોટું રોજગારદાતા છે, પણ તૃતીય ક્ષેત્ર સૌથી મોટું ઉત્પાદક.' આ સ્થિતિ સમજાવો અને વધુ રોજગાર ઊભો કરવાની બે રીતો સૂચવો, આશરે 120 શબ્દોમાં.\n\n"
  "**આદર્શ જવાબ:** 1973–74થી 2013–14 સુધી ઉત્પાદન સૌથી વધુ તૃતીય ક્ષેત્રમાં વધ્યું, જે 2013–14માં સૌથી મોટું ઉત્પાદક ક્ષેત્ર બન્યું. પણ ભારતના લગભગ અડધા કામદારો હજી પ્રાથમિક ક્ષેત્રમાં છે, કારણ કે દ્વિતીય અને તૃતીય ક્ષેત્રોએ ઉત્પાદનના પ્રમાણમાં રોજગાર વધાર્યો નથી. "
  "તેથી ખેતીમાં છૂપી બેરોજગારી છે: ખેતરોમાં જરૂર કરતાં વધુ લોકો કામ કરે છે, તેથી કેટલાકને દૂર કરવાથી ઉત્પાદન ઘટશે નહિ. "
  "ગ્રામીણ વિસ્તારોમાં સિંચાઈ, રસ્તા અને સંગ્રહ બનાવીને, ખેડૂતોને સસ્તું ધિરાણ આપીને, અને અર્ધ-ગ્રામીણ વિસ્તારોમાં દાળ મિલ જેવા કૃષિ-પ્રોસેસિંગ ઉદ્યોગો સ્થાપીને વધુ રોજગાર ઊભો થઈ શકે. શિક્ષણ, આરોગ્ય અને પ્રવાસનનો વિસ્તાર, અને મનરેગા જેવી યોજનાઓ પણ રોજગાર ઊભો કરી શકે."),
 "s6.summary.title": ("अध्याय सारांश", "પ્રકરણ સારાંશ"),
 "s6.summary.body": (
  "- आर्थिक गतिविधियाँ प्राथमिक (प्राकृतिक संसाधन), द्वितीयक (विनिर्माण) और तृतीयक (सेवाएँ) हैं; क्षेत्रक एक-दूसरे पर निर्भर हैं।\n"
  "- GDP किसी देश के भीतर एक वर्ष में उत्पादित सभी अंतिम वस्तुओं और सेवाओं का मूल्य है; केवल अंतिम वस्तुएँ गिनने से दोहरी गिनती से बचते हैं।\n"
  "- 2013–14 में तृतीयक क्षेत्रक सबसे बड़ा उत्पादक बना, पर प्राथमिक क्षेत्रक अब भी सबसे बड़ा रोज़गार देने वाला है, जिसमें प्रच्छन्न बेरोज़गारी है।\n"
  "- सिंचाई, परिवहन, सस्ते क़र्ज़, ग्रामीण उद्योगों, शिक्षा, स्वास्थ्य और पर्यटन से ज़्यादा रोज़गार आ सकता है; मनरेगा 100 दिन के काम की गारंटी देता है।\n"
  "- संगठित क्षेत्रक नियमित, सुरक्षित नौकरियाँ और लाभ देता है; असंगठित क्षेत्रक में कम वेतन वाला, असुरक्षित काम है और संरक्षण चाहिए।\n"
  "- सार्वजनिक उद्यम जन-कल्याण के लिए सरकार के स्वामित्व में हैं; निजी उद्यम लाभ के लिए व्यक्तियों या कंपनियों के स्वामित्व में।",
  "- આર્થિક પ્રવૃત્તિઓ પ્રાથમિક (કુદરતી સંસાધનો), દ્વિતીય (ઉત્પાદન) અને તૃતીય (સેવાઓ) છે; ક્ષેત્રો એકબીજા પર આધારિત છે.\n"
  "- GDP કોઈ દેશમાં એક વર્ષમાં ઉત્પન્ન બધી અંતિમ વસ્તુઓ અને સેવાઓનું મૂલ્ય છે; ફક્ત અંતિમ વસ્તુઓ ગણવાથી બેવડી ગણતરી ટળે છે.\n"
  "- 2013–14માં તૃતીય ક્ષેત્ર સૌથી મોટું ઉત્પાદક બન્યું, પણ પ્રાથમિક ક્ષેત્ર હજી સૌથી મોટું રોજગારદાતા છે, જેમાં છૂપી બેરોજગારી છે.\n"
  "- સિંચાઈ, પરિવહન, સસ્તું ધિરાણ, ગ્રામીણ ઉદ્યોગો, શિક્ષણ, આરોગ્ય અને પ્રવાસનથી વધુ રોજગાર મળી શકે; મનરેગા 100 દિવસના કામની ગૅરંટી આપે છે.\n"
  "- સંગઠિત ક્ષેત્ર નિયમિત, સલામત નોકરીઓ અને લાભ આપે છે; અસંગઠિત ક્ષેત્રમાં ઓછા વેતનવાળું, અસલામત કામ છે અને રક્ષણ જોઈએ.\n"
  "- જાહેર સાહસો જનકલ્યાણ માટે સરકારની માલિકીનાં છે; ખાનગી સાહસો નફા માટે વ્યક્તિઓ કે કંપનીઓની માલિકીનાં છે."),
 "s6.examtips.title": ("बोर्ड परीक्षा के सुझाव", "બોર્ડ પરીક્ષા માટેની ટિપ્સ"),
 "s6.examtips.body": (
  "- 2025-26 के प्रतिदर्श प्रश्न-पत्र में अल्प-बेरोज़गारी का कारण पूछा गया (ज़रूरत से ज़्यादा कामगार; उत्तर A), तृतीयक क्षेत्रक दूसरे क्षेत्रकों की मदद कैसे करता है इसका उदाहरण (परिवहन और खुदरा पर निर्भर जूता कारख़ाना; उत्तर B), और 5 अंक का विकल्प: संगठित और असंगठित क्षेत्रक के अंतर, या निजीकरण के सकारात्मक और नकारात्मक प्रभाव।\n"
  "- 3/5 अंक के पसंदीदा प्रश्न: उदाहरणों सहित तीन क्षेत्रक, GDP और अंतिम वस्तुएँ, तृतीयक क्षेत्रक का उदय, प्रच्छन्न बेरोज़गारी, मनरेगा, संगठित बनाम असंगठित, सार्वजनिक बनाम निजी।\n"
  "- तुलना वाले प्रश्नों में बिंदु जोड़ियों में लिखें (संगठित: ... / असंगठित: ...)।",
  "- 2025-26ના નમૂનાના પ્રશ્નપત્રમાં અલ્પ રોજગારીનું કારણ પુછાયું (જરૂર કરતાં વધુ કામદારો; જવાબ A), તૃતીય ક્ષેત્ર બીજાં ક્ષેત્રોને કેવી રીતે ટેકો આપે છે તેનું ઉદાહરણ (પરિવહન અને છૂટક વેચાણ પર આધારિત જૂતાંનું કારખાનું; જવાબ B), અને 5 ગુણનો વિકલ્પ: સંગઠિત અને અસંગઠિત ક્ષેત્રના તફાવત, કે ખાનગીકરણની હકારાત્મક અને નકારાત્મક અસરો.\n"
  "- 3/5 ગુણના પ્રિય પ્રશ્નો: ઉદાહરણો સાથે ત્રણ ક્ષેત્રો, GDP અને અંતિમ વસ્તુઓ, તૃતીય ક્ષેત્રનો ઉદય, છૂપી બેરોજગારી, મનરેગા, સંગઠિત સામે અસંગઠિત, જાહેર સામે ખાનગી.\n"
  "- સરખામણીના પ્રશ્નોમાં મુદ્દા જોડીમાં લખો (સંગઠિત: ... / અસંગઠિત: ...)."),
 "s6.flash1.front": ("GDP क्या है?", "GDP શું છે?"),
 "s6.flash1.back": ("किसी देश के भीतर किसी विशेष वर्ष में उत्पादित सभी अंतिम वस्तुओं और सेवाओं का मूल्य।", "કોઈ દેશમાં ચોક્કસ વર્ષ દરમિયાન ઉત્પન્ન થયેલી બધી અંતિમ વસ્તુઓ અને સેવાઓનું મૂલ્ય."),
 "s6.flash2.front": ("प्रच्छन्न बेरोज़गारी क्या है?", "છૂપી બેરોજગારી શું છે?"),
 "s6.flash2.back": ("ऐसी स्थिति जिसमें ज़रूरत से ज़्यादा लोग काम करते हैं, इसलिए कुछ पूरी तरह रोज़गार में नहीं; उनके हटने से उत्पादन नहीं घटता।", "એવી સ્થિતિ જેમાં જરૂર કરતાં વધુ લોકો કામ કરે છે, તેથી કેટલાક સંપૂર્ણ રોજગારીમાં નથી; તેમને દૂર કરવાથી ઉત્પાદન ઘટતું નથી."),
 "s6.flash3.front": ("मनरेगा 2005 किसकी गारंटी देता है?", "મનરેગા 2005 શાની ગૅરંટી આપે છે?"),
 "s6.flash3.back": ("ग्रामीण क्षेत्रों में काम करने में सक्षम और ज़रूरतमंद लोगों को साल में 100 दिन का रोज़गार; काम न मिलने पर भत्ता; एक-तिहाई नौकरियाँ महिलाओं के लिए।", "ગ્રામીણ વિસ્તારોમાં કામ કરવા સક્ષમ અને જરૂરિયાતમંદ લોકોને વર્ષમાં 100 દિવસનો રોજગાર; કામ ન મળે તો ભથ્થું; એક-તૃતીયાંશ નોકરીઓ સ્ત્રીઓ માટે."),
 "s6.flash4.front": ("सार्वजनिक और निजी क्षेत्रक में क्या अंतर है?", "જાહેર અને ખાનગી ક્ષેત્ર વચ્ચે શો તફાવત છે?"),
 "s6.flash4.back": ("सार्वजनिक क्षेत्रक: सरकार परिसंपत्तियों की मालिक है और जन-कल्याण के लिए सेवाएँ देती है। निजी क्षेत्रक: व्यक्ति या कंपनियाँ परिसंपत्तियों की मालिक हैं और लाभ के लिए काम करती हैं।", "જાહેર ક્ષેત્ર: સરકાર અસ્કયામતોની માલિક છે અને જનકલ્યાણ માટે સેવાઓ આપે છે. ખાનગી ક્ષેત્ર: વ્યક્તિઓ કે કંપનીઓ અસ્કયામતોની માલિક છે અને નફા માટે કામ કરે છે."),
}
